from typing import List

class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)

        for row in range(n):
            diagonal = []
            i, j = row, 0
            while i < n and j < n:
                diagonal.append(grid[i][j])
                i += 1
                j += 1

            diagonal.sort(reverse=True)

            i, j = row, 0
            for value in diagonal:
                grid[i][j] = value
                i += 1
                j += 1

        for col in range(1, n):
            diagonal = []
            i, j = 0, col
            while i < n and j < n:
                diagonal.append(grid[i][j])
                i += 1
                j += 1

            diagonal.sort()

            i, j = 0, col
            for value in diagonal:
                grid[i][j] = value
                i += 1
                j += 1

        return grid
